const pptxgen = require("pptxgenjs");

// Color palette - Midnight Executive (professional, data-forward)
const COLORS = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  darkText: "1E293B",
  mutedText: "64748B",
  accent: "0D9488",
  accentLight: "14B8A6",
  lightBg: "F8FAFC",
  cardBg: "FFFFFF",
  gridLine: "E2E8F0",
  chartColors: ["1E2761", "0D9488", "14B8A6", "CADCFC", "F96167", "F9E795", "6D2E46", "028090"]
};

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Stack Overflow";
pres.title = "Developer Workforce & Compensation Trends — 2024 Stack Overflow Survey";

// ============================================================
// SLIDE 1: Title Slide
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.navy };

  // Title
  slide.addText("Developer Workforce & Compensation Trends", {
    x: 0.5, y: 1.8, w: 9, h: 1.0,
    fontSize: 36, fontFace: "Arial Black", color: COLORS.white, bold: true
  });

