    x: 0.5, y: 0.35, w: 9, h: 0.65,
    fontSize: 24, fontFace: "Arial", bold: true, color: COLORS.white
  });

  const takeaways = [
    {
      num: "1",
      title: "Plan for More Contractors",
      body: "U.S. full-time employment fell 4.2 pp year-over-year. Freelancing and contracting remain significant at 16%+. Build flexibility into headcount plans."
    },
    {
      num: "2",
      title: "Hybrid Is the Default — In-Person Is Growing",
      body: "Despite rising in-person (15% → 20% since 2022), hybrid still dominates at 42%. Remote-friendly roles remain competitive differentiators."
    },
    {
      num: "3",
      title: "DevRel & SRE Command Premium Pay",
      body: "Dev Advocates ($124K), Managers ($116K), SREs ($99K), and Cloud Infra ($97K) lead salaries. These critical-role retention strategies warrant investment."
    },
    {
      num: "4",
      title: "Niche Languages Correlate with Higher Pay",
      body: "Erlang, Clojure, and Elixir devs earn $93K+ median. Mainstream languages (JavaScript, PHP) sit well below $65K. Language diversity has a pay premium."
    },
    {
      num: "5",
      title: "Engage Developers in Purchase Decisions",
      body: "62% of developers influence tech buying. Vendor strategies should target individual contributors and managers — not just executives."
    }
  ];

  const cardWidth = 4.3;
  const cardHeight = 0.82;
  const startY = 1.15;
  const gapY = 0.08;

  takeaways.forEach((item, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const xPos = 0.5 + col * 4.7;
    const yPos = startY + row * (cardHeight + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: xPos, y: yPos, w: cardWidth, h: cardHeight,
      fill: { color: COLORS.white, transparency: 10 }
    });

    // Number badge
    slide.addShape(pres.shapes.OVAL, {
      x: xPos + 0.12, y: yPos + 0.15, w: 0.4, h: 0.4,
      fill: { color: COLORS.accent }
    });
    slide.addText(item.num, {
      x: xPos + 0.12, y: yPos + 0.15, w: 0.4, h: 0.4,
      fontSize: 14, bold: true, color: COLORS.white,
      align: "center", valign: "middle"
    });

    // Title and body
    slide.addText(item.title, {
      x: xPos + 0.62, y: yPos + 0.08, w: cardWidth - 0.75, h: 0.28,
      fontSize: 11, bold: true, color: COLORS.navy, margin: 0
    });
    slide.addText(item.body, {
      x: xPos + 0.62, y: yPos + 0.36, w: cardWidth - 0.75, h: 0.42,
      fontSize: 8.5, color: COLORS.mutedText, margin: 0, valign: "top"
    });
  });

  // Source attribution
  slide.addText("Source: stackoverflow.co/survey/2024/work", {
    x: 0.5, y: 5.15, w: 9, h: 0.25,
    fontSize: 9, color: COLORS.iceBlue, italic: true
  });
